INSERT INTO ai_rules (id, rule_text, source_count, active, created_at, updated_at) VALUES
('rule-0025', 'כשמזכירים בגוף הכתבה מקור אמיתי שכדאי להגיע אליו (תיעוד רשמי, כלי ספציפי, סרטון רלוונטי), להפוך את זה לקישור בדיוק במקום שבו הוא מוזכר, לא לשמור אותו רק לרשימת מקורות בסוף.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0026', 'תמונה או תרשים צריכים להיות הדבר הספציפי שמתואר, לא איור כללי של הנושא. תרשים גנרי במקום שבו אמור להיות משהו קונקרטי הוא סימן שהתוכן לא באמת עבר בדיקה מעשית.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z');
